function normalizeEmployeeType(type){return String(type||" ").trim().toLowerCase()==="teaching"?"Teaching":"Non-Teaching"}function normalizeRole(role){const v=String(role||'').trim().toLowerCase();return v==='admin'||v.includes('personnel')||v.includes('authority')||v==='superintendent'?'Admin':v==='employee'?'Employee':String(role||'')}
