function makeUrl(params={}){if(!isConfigured())throw new Error('Configure APPS_SCRIPT_API_URL at the top of portal.js.');const url=new URL(APPS_SCRIPT_API_URL);Object.entries(params).forEach(([k,v])=>{if(v!==undefined&&v!==null)url.searchParams.set(k,String(v))});return url}
async function sheetRequest(path='',params={},options={}){const method=String(options.method||'GET').toUpperCase(),query={...params};let payload=null;if(method==='POST'){let body={};try{body=JSON.parse(options.body||'{}')}catch{}const sheet=params.sheet||body.sheet;if(path){const match=path.match(/^\/([^/]+)\/(.*)$/);if(!match)throw new Error('Unsupported Apps Script update path.');payload={action:'update',sheet,keyField:match[1],keyValue:decodeURIComponent(match[2]),data:body.data||{}}}else if(body.action==='delete'){if(!body.keyField||body.keyValue===undefined)throw new Error('Delete requests require keyField and keyValue.');payload={action:'delete',sheet,keyField:String(body.keyField),keyValue:String(body.keyValue)}}else payload={action:'create',sheet,data:Array.isArray(body.data)?body.data[0]:body.data}}const url=makeUrl(method==='GET'?query:{sheet:params.sheet});const key=cacheKey(url);const fetchFresh=async()=>{const response=await fetch(url,{method,mode:'cors',redirect:'follow',headers:method==='POST'?{'Accept':'application/json','Content-Type':'text/plain;charset=utf-8'}:{'Accept':'application/json'},...(payload?{body:JSON.stringify(payload)}:{})});const text=await response.text();let data=null;try{data=text?JSON.parse(text):null}catch{}if(!response.ok)throw new Error(data?.error||data?.message||'Apps Script request failed ('+response.status+').');if(data&&data.success===false)throw new Error(data.error||data.message||'Apps Script rejected the request.');return data?.rows??data?.data??data};if(method==='GET'){const cached=getCachedRead(key);if(cached?.fresh&&!options.force)return cached.value;if(cached&&!options.force){if(!readRequests.has(key)){const pending=fetchFresh().then(data=>{setCachedRead(key,data);window.dispatchEvent(new CustomEvent('portal:cache-refreshed',{detail:{sheet:params.sheet,params,data}}));return data}).catch(()=>{}).finally(()=>readRequests.delete(key));readRequests.set(key,pending)}return cached.value}if(readRequests.has(key))return readRequests.get(key);const pending=fetchFresh().then(data=>{setCachedRead(key,data);return data}).finally(()=>readRequests.delete(key));readRequests.set(key,pending);return pending}try{const result=await fetchFresh();invalidateSheetCache(params.sheet||payload?.sheet);return result}catch(err){throw new Error('Could not reach Apps Script. Check the Web App deployment permissions and CORS response for this site origin. '+err.message)}}
const sheetRows=async (sheet,options={})=>{const rows=await sheetRequest('',{sheet},options);if(!Array.isArray(rows))throw new Error('Apps Script did not return rows for the '+sheet+' tab.');return rows};
const addRow=(sheet,row)=>sheetRequest('',{sheet},{method:'POST',body:JSON.stringify({data:row})});
