const findUser=async id=>{const key=String(id);if(userLookups.has(key))return userLookups.get(key);const pending=sheetRows('Users').then(rows=>{const user=rows.find(row=>String(row.EmployeeID)===key);if(!user)throw new Error('Employee record was not found in Users.');userLookups.set(key,user);return user}).finally(()=>{if(userLookups.get(key)===pending)userLookups.delete(key)});userLookups.set(key,pending);return pending};
function makeAudit(actor,action,target,details){return {LogID:'LOG-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),Timestamp:new Date().toISOString(),ActorID:String(actor?.EmployeeID||''),ActorName:String(actor?.Name||''),Role:String(actor?.Role||''),Action:String(action),TargetID:String(target||''),Details:typeof details==='string'?details:JSON.stringify(details||{})}}
function formatAuditTimestamp(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value||'');const datePart=new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(date),timePart=new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(date);return datePart+' · '+timePart}
function auditDate(value,includeYear=true){const raw=String(value||'');let date;if(/^\d{4}-\d{2}-\d{2}$/.test(raw))date=new Date(raw+'T12:00:00');else date=new Date(raw);if(Number.isNaN(date.getTime()))return raw;return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',...(includeYear?{year:'numeric'}:{})}).format(date)}
function auditDateRange(start,end){const a=auditDate(start,false),b=auditDate(end,true),startYear=String(start||'').slice(0,4),endYear=String(end||'').slice(0,4);return startYear&&endYear&&startYear!==endYear?auditDate(start,true)+' – '+b:a+' – '+b}
function auditDays(value){const n=number(value);return Number.isInteger(n)?String(n):String(Number(n.toFixed(1)))}
function dedupeRapidLoginLogs(logs){const seen=new Set();return logs.filter(log=>{if(String(log.Action||'').toLowerCase()!=='login')return true;const stamp=new Date(log.Timestamp).getTime();if(Number.isNaN(stamp))return true;const key=String(log.ActorID)+'|'+Math.floor(stamp/1000);if(seen.has(key))return false;seen.add(key);return true})}
function formatAuditDetails(log){
 const action=String(log.Action||''),lower=action.toLowerCase(),d=parseDetails(log.Details);
 if(lower==='login')return 'Signed in to the '+(String(log.Role||'Employee')==='Admin'?'Admin':'Employee')+' Portal';
 if(lower==='leave application submitted'&&d.leaveType){const days=auditDays(d.workingDays);return 'Filed '+d.leaveType+' for '+auditDateRange(d.start,d.end)+' ('+days+' working '+(Number(d.workingDays)===1?'day':'days')+')'}
 if(lower==='pending leave application deleted'&&d.leaveType)return 'Cancelled pending '+d.leaveType+' request ('+auditDays(d.workingDays)+' working '+(Number(d.workingDays)===1?'day':'days')+')';
 if(lower.startsWith('leave application approved')||lower.startsWith('leave application disapproved')){const verb=lower.includes('approved')?'Approved':'Disapproved',leave=d.leaveType||'leave request',days=auditDays(d.workingDays),deducted=number(d.deductedDays)||(d.deductedColumn?number(d.workingDays):0),balance=d.balanceName||(d.deductedColumn==='VacationBalance'&&/VSC|illness-related absence|personal absence/i.test(leave)?'VSC':d.deductedColumn?auditCreditLabel(d.deductedColumn):'leave balance');if(deducted>0){const remaining=d.balanceAfter===undefined?'':' (Remaining: '+number(d.balanceAfter).toFixed(1)+')';return verb+' '+leave+' ('+days+' working days) · Deducted '+deducted.toFixed(1)+' days from '+balance+remaining}return verb+' '+leave+' ('+days+' working days) · No leave balance deducted'}
 if(lower==='vacation service credits issued by special order')return 'Admin updated VSC balance from '+number(d.balanceBefore).toFixed(1)+' to '+number(d.balanceAfter).toFixed(1)+' days · '+auditDays(d.days)+' days issued under '+String(d.specialOrder||'Special Order');
 if(lower.includes('employee leave credits updated')||lower.includes('classification and credits updated')){if(d.changes&&typeof d.changes==='object'){const changes=Object.entries(d.changes).map(([key,v])=>auditCreditLabel(key)+' from '+number(v.from).toFixed(1)+' to '+number(v.to).toFixed(1)+' days');if(changes.length)return 'Admin updated '+changes.join('; ')}if(d.employeeType?.from!==d.employeeType?.to)return 'Admin changed employee classification from '+String(d.employeeType.from||'Not set')+' to '+String(d.employeeType.to||'Not set');return 'Admin updated employee leave credits'}
 if(lower==='employee account deleted')return 'Admin deleted the employee account for '+String(d.employeeName||log.TargetID);
 if(lower.includes('statutory'))return action;
 const plain=typeof log.Details==='string'?log.Details:'';if(d.reason)return String(d.reason);if(d&&Object.keys(d).length)return Object.entries(d).map(([key,value])=>auditCreditLabel(key)+': '+auditDisplayValue(value)).join(' · ');return plain||action
}function auditDisplayValue(value){if(value===null||value===undefined||value==='')return '—';if(Array.isArray(value))return value.map(auditDisplayValue).join(', ');if(typeof value==='object')return Object.entries(value).map(([key,item])=>auditCreditLabel(key)+' '+auditDisplayValue(item)).join(', ');return String(value)}
function auditCreditLabel(key){return ({VacationBalance:'Vacation Leave balance',VacationLeaveBalance:'Vacation Leave balance',VSCBalance:'VSC balance',SickBalance:'Sick Leave balance',WellnessBalance:'Wellness Leave balance',SpecialPrivilegeBalance:'Special Privilege Leave balance',EmployeeType:'employee classification'})[key]||String(key).replace(/([A-Z])/g,' $1').trim()}
const loginAuditSeconds=new Map();
async function logAudit(actor,action,target,details){if(String(action).toLowerCase()==='login'){const actorID=String(actor?.EmployeeID||''),key='jupi-login-audit-second:'+actorID,current=Math.floor(Date.now()/1000);if(loginAuditSeconds.get(actorID)===current)return null;loginAuditSeconds.set(actorID,current);try{const previous=Number(sessionStorage.getItem(key));if(previous===current)return null;sessionStorage.setItem(key,String(current))}catch{}}const row=makeAudit(actor,action,target,details);await addRow('AuditLogs',row);return row}
async function personalAuditLogs(session,apps){const own=await sheetRequest('/search',{sheet:'AuditLogs',ActorID:session.EmployeeID});const related=await Promise.all(apps.map(a=>sheetRequest('/search',{sheet:'AuditLogs',TargetID:a.ApplicationID}).catch(()=>[])));const all=[...(Array.isArray(own)?own:[]),...related.flatMap(x=>Array.isArray(x)?x:[])];return [...new Map(all.map((x,i)=>[String(x.LogID||x.Timestamp+'-'+i),x])).values()]}
async function derivePassword(value,salt,iterations){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits)).map(x=>x.toString(16).padStart(2,'0')).join('')}
async function passwordMatches(entered,saved){const value=String(saved||'');if(value.startsWith('pbkdf2$')){if(!globalThis.crypto?.subtle)throw new Error('Secure password verification requires HTTPS or localhost.');const [,rounds,saltText,expected]=value.split('$'),salt=Uint8Array.from(atob(saltText),c=>c.charCodeAt(0));return await derivePassword(entered,salt,Number(rounds))===expected}if(value.startsWith('sha256:')){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(entered));return value.slice(7).toLowerCase()===Array.from(new Uint8Array(bytes)).map(x=>x.toString(16).padStart(2,'0')).join('')}return value===entered}
async function passwordHash(value){const salt=crypto.getRandomValues(new Uint8Array(16)),rounds=210000;return 'pbkdf2$'+rounds+'$'+btoa(String.fromCharCode(...salt))+'$'+await derivePassword(value,salt,rounds)}
function hasSession(role){const s=getSession();if(!s||!s.EmployeeID||normalizeRole(s.Role)!==role){location.href='login.html';return null}document.querySelectorAll('[data-profile-name]').forEach(el=>el.textContent=s.Name);return s}
function setProfilePicture(){const u=getSession(),photo=document.querySelector('#employee-photo'),avatar=document.querySelector('#employee-avatar'),input=document.querySelector('#employee-photo-input');if(!u||!photo||!avatar)return;const key='jupi-profile-photo-'+u.EmployeeID;try{const saved=localStorage.getItem(key);if(saved){photo.src=saved;photo.hidden=false;avatar.hidden=true}}catch{}input?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>3*1024*1024){toast('Choose a JPG, PNG, or WebP photo under 3 MB.');return}const reader=new FileReader();reader.onload=()=>{photo.src=reader.result;photo.hidden=false;avatar.hidden=true;try{localStorage.setItem(key,reader.result)}catch{}};reader.readAsDataURL(f)})}
function ensureFormModal(){let dialog=document.querySelector('#form6-dialog');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='form6-dialog';dialog.className='form6-dialog';dialog.innerHTML='<div class="form6-actions"><button type="button" class="btn outline" data-form6-close>Close</button><button type="button" class="btn gold" data-form6-print>Print Form 6</button></div><div id="form6-content"></div>';document.body.append(dialog);dialog.querySelector('[data-form6-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-form6-print]').addEventListener('click',()=>window.print());return dialog}
function parseDetails(v){try{return typeof v==='string'?JSON.parse(v||'{}'):v||{}}catch{return {reason:String(v||'')}}}
function balanceLabel(c,u){if(c==='VacationBalance'&&String(u?.EmployeeType||'').toLowerCase()==='teaching')return 'Vacation Service Credits (VSC)';return CREDIT_LABELS[c]||c}
function getBalanceColumn(type){const t=String(type||'').toLowerCase();if(['vacation service credits (vsc)','illness-related absence','personal absence'].includes(t))return 'VacationBalance';if(t==='wellness leave')return 'WellnessBalance';if(t==='special privilege leave')return 'SpecialPrivilegeBalance';if(t==='sick leave')return 'SickBalance';if(t==='vacation leave'||t==='mandatory/forced leave')return 'VacationBalance';return null}
const STATUTORY_YEAR=new Date().getFullYear(),ANNUAL_LEAVE_CAPS=[{key:'soloParent',label:'Solo Parent Leave',cap:7},{key:'wellness',label:'Wellness Leave',cap:5},{key:'emergency',label:'Special Emergency Leave',cap:5}],STATUTORY_LEAVES=[{key:'soloParent',label:'Solo Parent Leave',cap:7,annual:true},{key:'emergency',label:'Special Emergency Leave',cap:5,annual:true},{key:'maternity',label:'Maternity Leave',cap:105,event:true},{key:'paternity',label:'Paternity Leave',cap:7,event:true},{key:'vawc',label:'VAWC Leave',cap:10,event:true},{key:'adoption',label:'Adoption Leave',cap:60,event:true},{key:'women',label:'Special Leave Benefits for Women',cap:60,event:true},{key:'rehabilitation',label:'Rehabilitation Leave',event:true},{key:'lwop',label:'Leave Without Pay (LWOP)',event:true}];
function statutoryLeaveKey(type){const t=String(type||'').toLowerCase().replace(/[^a-z]/g,'');if(t.includes('soloparent'))return 'soloParent';if(t.includes('wellness'))return 'wellness';if(t.includes('specialemergency')||t.includes('calamity'))return 'emergency';if(t.includes('maternity'))return 'maternity';if(t.includes('paternity'))return 'paternity';if(t.includes('vawc'))return 'vawc';if(t.includes('adoption'))return 'adoption';if(t.includes('specialleavebenefitsforwomen'))return 'women';if(t.includes('rehabilitation'))return 'rehabilitation';if(t.includes('leavewithoutpay')||t==='lwop')return 'lwop';return null}
function leaveDaysInYear(app,year){const start=String(app.StartDate||''),end=String(app.EndDate||'');if(/^\d{4}-\d{2}-\d{2}$/.test(start)&&/^\d{4}-\d{2}-\d{2}$/.test(end)){let inYear=0,total=0,d=new Date(start+'T12:00:00'),last=new Date(end+'T12:00:00');for(;d<=last;d.setDate(d.getDate()+1))if(d.getDay()!==0&&d.getDay()!==6){total++;if(d.getFullYear()===year)inYear++}if(inYear===total)return number(app.WorkingDays);return total?number(app.WorkingDays)*inYear/total:0}return String(app.DateFiled||'').slice(0,4)===String(year)?number(app.WorkingDays):0}
function statutoryUsage(apps,employeeID,key,year=STATUTORY_YEAR,statuses=['approved'],excludeID=''){return apps.filter(a=>String(a.EmployeeID)===String(employeeID)&&statutoryLeaveKey(a.LeaveType)===key&&statuses.includes(String(a.Status||'').toLowerCase())&&String(a.ApplicationID)!==String(excludeID)).reduce((total,a)=>total+leaveDaysInYear(a,year),0)}
function statutoryRowsMarkup(apps,employeeID,items){return items.map(item=>{const used=statutoryUsage(apps,employeeID,item.key),remaining=item.cap===undefined?null:Math.max(0,item.cap-used),value=item.annual?used.toFixed(1)+' used / '+item.cap.toFixed(1)+' days max · '+remaining.toFixed(1)+' remaining':used.toFixed(1)+' approved days this year'+(item.cap?' · '+item.cap.toFixed(1)+' days / event':' · No fixed annual cap');return '<tr><td>'+safe(item.label)+'</td><td>'+safe(value)+'</td></tr>'}).join('')}
function statutoryTallyMarkup(apps,employeeID,compact=false){const annual=STATUTORY_LEAVES.filter(x=>x.annual),event=STATUTORY_LEAVES.filter(x=>!x.annual),usedEvents=event.filter(x=>statutoryUsage(apps,employeeID,x.key)>0),rows=[...annual,...usedEvents];return '<div class="table-wrap"><table><thead><tr><th>Leave type</th><th>Approved usage / limit</th></tr></thead><tbody>'+statutoryRowsMarkup(apps,employeeID,rows,compact)+'</tbody></table></div>'}
function statutoryEmployeeMarkup(apps,employeeID){const events=STATUTORY_LEAVES.filter(x=>!x.annual);return statutoryTallyMarkup(apps,employeeID)+ '<button type="button" class="btn outline" data-statutory-toggle aria-expanded="false">View all statutory leave caps</button><div data-statutory-extra hidden><div class="table-wrap"><table><thead><tr><th>Event-based leave</th><th>Approved usage / event cap</th></tr></thead><tbody>'+statutoryRowsMarkup(apps,employeeID,events)+'</tbody></table></div></div>'}
function annualCapWarning(apps,app){const key=statutoryLeaveKey(app.LeaveType),limit=ANNUAL_LEAVE_CAPS.find(x=>x.key===key);if(!limit)return null;const start=String(app.StartDate||'').slice(0,4),year=/^\d{4}$/.test(start)?Number(start):STATUTORY_YEAR,requested=leaveDaysInYear(app,year),used=statutoryUsage(apps,app.EmployeeID,key,year,['approved','pending'],app.ApplicationID);return requested+used>limit.cap?{label:limit.label,cap:limit.cap,used,requested,remaining:Math.max(0,limit.cap-used),year}:null}
